export function sum(numbers) {
  assertNonEmpty(numbers);
  return numbers.reduce((a, b) => a + b, 0);
}

export function mean(numbers) {
  assertNonEmpty(numbers);
  return sum(numbers) / numbers.length;
}

// 中位数：内部排序副本，不改动调用方数组
export function median(numbers) {
  assertNonEmpty(numbers);
  const sorted = [...numbers].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1
    ? sorted[mid]
    : (sorted[mid - 1] + sorted[mid]) / 2;
}

// 线性插值百分位：p50 应与 median 一致，p0/p100 即最小/最大值
export function percentile(numbers, p) {
  assertNonEmpty(numbers);
  if (!Number.isFinite(p) || p < 0 || p > 100) {
    throw new RangeError('p must be a finite number in [0, 100]');
  }
  const sorted = [...numbers].sort((a, b) => a - b);
  if (sorted.length === 1) return sorted[0];
  const rank = (p / 100) * (sorted.length - 1);
  const low = Math.floor(rank);
  const high = Math.ceil(rank);
  return low === high
    ? sorted[low]
    : sorted[low] + (rank - low) * (sorted[high] - sorted[low]);
}

function assertNonEmpty(numbers) {
  if (!Array.isArray(numbers) || numbers.length === 0) {
    throw new Error('numbers must be a non-empty array');
  }
}

