import { test } from 'node:test';
import assert from 'node:assert/strict';
import { sum, mean, median, percentile } from '../src/stats.js';

test('sum 加总正数与负数', () => {
  assert.equal(sum([1, 2, 3]), 6);
  assert.equal(sum([-5, 5, 10]), 10);
});

test('sum 对空数组抛错', () => {
  assert.throws(() => sum([]), /non-empty array/);
});

test('sum 对非数组输入抛错', () => {
  assert.throws(() => sum('123'), /non-empty array/);
  assert.throws(() => sum(null), /non-empty array/);
});

test('mean 计算平均值', () => {
  assert.equal(mean([2, 4, 6]), 4);
});

test('mean 单元素数组返回自身', () => {
  assert.equal(mean([42]), 42);
});

test('median 奇数长度取中间值（乱序输入）', () => {
  assert.equal(median([5, 1, 3]), 3);
});

test('median 偶数长度取两中间值均值', () => {
  assert.equal(median([4, 1, 3, 2]), 2.5);
});

test('median 不改动调用方数组', () => {
  const input = [9, 1, 5];
  median(input);
  assert.deepEqual(input, [9, 1, 5]);
});

test('percentile p50 与 median 一致', () => {
  const xs = [15, 20, 35, 40, 50];
  assert.equal(percentile(xs, 50), median(xs));
});

test('percentile p0/p100 为最小/最大值', () => {
  const xs = [7, 2, 9];
  assert.equal(percentile(xs, 0), 2);
  assert.equal(percentile(xs, 100), 9);
});

test('percentile 在数据点之间线性插值', () => {
  // rank = 0.25*(3-1) = 0.5 → 1 与 2 之间取半
  assert.equal(percentile([1, 2, 3], 25), 1.5);
});

test('percentile 非法 p 抛 RangeError', () => {
  assert.throws(() => percentile([1, 2], 101), RangeError);
  assert.throws(() => percentile([1, 2], -1), RangeError);
  assert.throws(() => percentile([1, 2], Number.NaN), RangeError);
});

