// 字符串工具：全部返回新字符串，不改输入；非法参数显式抛错
export function slugify(text) {
  assertString(text);
  return text
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '') // 去掉变音符号
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '');
}

