import { test } from 'node:test';
import assert from 'node:assert/strict';
import { slugify, truncate, toCamelCase, titleCase } from '../src/strings.js';

test('slugify 把空格和标点折叠为连字符', () => {
  assert.equal(slugify('Hello, World!'), 'hello-world');
});

test('slugify 去除变音符号（NFKD 分解）', () => {
  assert.equal(slugify('Café Über'), 'cafe-uber');
});

test('slugify 去掉首尾分隔符', () => {
  assert.equal(slugify('  --hello world--  '), 'hello-world');
});

test('slugify 保留 Unicode 字母（拼音/西里尔）', () => {
  assert.equal(slugify('你好 world'), '你好-world');
  assert.equal(slugify('Привет Мир'), 'привет-мир');
});

test('slugify 对非字符串抛 TypeError', () => {
  assert.throws(() => slugify(42), TypeError);
});

test('truncate 超长文本截断并加省略号后缀', () => {
  assert.equal(truncate('hello world', 8), 'hello w…');
});

test('truncate 未超长时原样返回且不加后缀', () => {
  assert.equal(truncate('short', 10), 'short');
  assert.equal(truncate('exactly8', 8), 'exactly8');
});

test('truncate 极小 maxLength 退化为纯后缀填充', () => {
  assert.equal(truncate('abcdef', 1), '…');
  assert.equal(truncate('abcdef', 2), '…'.repeat(2));
});

test('truncate 非法 maxLength 抛 RangeError', () => {
  assert.throws(() => truncate('x', 0), RangeError);
  assert.throws(() => truncate('x', 1.5), RangeError);
});

test('toCamelCase 分隔词转小驼峰', () => {
  assert.equal(toCamelCase('foo-bar baz'), 'fooBarBaz');
  assert.equal(toCamelCase('HTTP_response'), 'httpResponse');
});

test('toCamelCase 无有效词时返回空串', () => {
  assert.equal(toCamelCase('!!!'), '');
});

test('titleCase 每个词首字母大写其余小写', () => {
  assert.equal(titleCase('hello WORLD foo'), 'Hello World Foo');
});

