// 集合工具：不改动输入数组；shuffle 通过可注入 RNG 保证可测试
export function chunk(array, size) {
  if (!Array.isArray(array)) throw new TypeError('array must be an array');
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('size must be an integer >= 1');
  }
  const result = [];
  for (let i = 0; i < array.length; i += size) {
    result.push(array.slice(i, i + size));
  }
  return result;
}

// SameValueZero 去重，保留首次出现顺序（NaN 视为相等）
export function unique(array) {
  if (!Array.isArray(array)) throw new TypeError('array must be an array');
  const seen = new Set();
  const result = [];
  for (const item of array) {
    if (!seen.has(item)) {
      seen.add(item);
      result.push(item);
    }
  }
  return result;
}

export function groupBy(array, keyFn) {
  if (!Array.isArray(array)) throw new TypeError('array must be an array');
  if (typeof keyFn !== 'function') throw new TypeError('keyFn must be a function');
  const groups = new Map();
  for (const item of array) {
    const key = keyFn(item);
    const list = groups.get(key);
    if (list) list.push(item);
    else groups.set(key, [item]);
  }
  return groups;
}

// Fisher–Yates 洗牌：默认 Math.random，测试注入确定性 RNG
export function shuffle(array, rng = Math.random) {
  if (!Array.isArray(array)) throw new TypeError('array must be an array');
  if (typeof rng !== 'function') throw new TypeError('rng must be a function');
  const result = [...array];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

